import React, { useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import { api, normalizeArrayPayload, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

export default function FraudPage() {
  const [cycles, setCycles] = useState([]);
  const [logs, setLogs] = useState([]);
  const [tab, setTab] = useState('logs');
  const [loading, setLoading] = useState(true);

  const loadAll = async () => {
    try {
      const [cycleRes, logRes] = await Promise.all([
        api.fetchFraudCycles(),
        api.fetchRiskLogs(),
      ]);
      setCycles(normalizeArrayPayload(cycleRes));
      setLogs(normalizeArrayPayload(logRes));
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
    const id = setInterval(loadAll, 2000);

    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });
    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);

    return () => {
      clearInterval(id);
      socket.disconnect();
    };
  }, []);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container" style={{ maxWidth: 1280 }}>
        <div style={{ marginBottom: 28 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, color: '#ff6969', fontSize: 13, fontWeight: 900, letterSpacing: '0.15em', textTransform: 'uppercase' }}>
            <span className="live-dot-red blink" />
            Fraud Engine Active
          </div>
          <h1 style={{ fontSize: 28, fontWeight: 900, margin: '14px 0 8px' }}>
            Circular Trading <span style={{ color: '#ff5555', textShadow: '0 0 18px rgba(255,85,85,0.25)' }}>Detection</span>
          </h1>
          <div style={{ color: '#858d7f', fontSize: 16 }}>
            WITH RECURSIVE SQL engine scanning all trade cycles in real time
          </div>
        </div>

        <div className="grid-3" style={{ marginBottom: 18 }}>
          <div className="glass-strong" style={{ padding: 24 }}>
            <div style={{ color: '#848b7d', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase' }}>Total Cycles</div>
            <div style={{ color: '#ff5555', fontSize: 46, fontWeight: 900, marginTop: 12 }}>{cycles.length}</div>
          </div>
          <div className="glass-strong" style={{ padding: 24 }}>
            <div style={{ color: '#848b7d', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase' }}>Critical (≥70)</div>
            <div style={{ color: '#ff5555', fontSize: 46, fontWeight: 900, marginTop: 12 }}>
              {logs.filter((l) => Number(l.risk_score || 0) >= 70).length}
            </div>
          </div>
          <div className="glass-strong" style={{ padding: 24 }}>
            <div style={{ color: '#848b7d', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase' }}>Risk Log Entries</div>
            <div style={{ color: '#ffb020', fontSize: 46, fontWeight: 900, marginTop: 12 }}>{logs.length}</div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: 10, marginBottom: 18 }}>
          <button className={`btn-ghost ${tab === 'cycles' ? 'active' : ''}`} onClick={() => setTab('cycles')}>🔁 Fraud Cycles ({cycles.length})</button>
          <button className={`btn-ghost ${tab === 'logs' ? 'active' : ''}`} onClick={() => setTab('logs')}>📋 Risk Logs ({logs.length})</button>
        </div>

        {loading ? (
          <div className="glass-strong empty-state">Loading fraud engine...</div>
        ) : tab === 'cycles' ? (
          <div style={{ display: 'grid', gap: 16 }}>
            {!cycles.length && <div className="glass-strong empty-state">No detected cycles yet.</div>}
            {cycles.map((cycle, i) => (
              <div key={i} className="glass-strong card-hover" style={{ padding: 22 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', gap: 14, alignItems: 'flex-start' }}>
                  <div>
                    <div style={{ color: '#ff6b6b', fontSize: 12, fontWeight: 900, letterSpacing: '0.1em', textTransform: 'uppercase' }}>
                      Cycle #{i + 1}
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, marginTop: 14 }}>
                      {(cycle.cycle || cycle.path || []).map((node, idx, arr) => (
                        <React.Fragment key={idx}>
                          <span className="tag">T{node}</span>
                          {idx < arr.length - 1 && <span style={{ color: '#65705f' }}>→</span>}
                        </React.Fragment>
                      ))}
                    </div>
                    <div style={{ color: '#86907f', marginTop: 14, fontSize: 13 }}>
                      {cycle.explanation || cycle.reason || 'Recursive cycle detected in trade graph'}
                    </div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div style={{ color: '#ff5555', fontSize: 36, fontWeight: 900 }}>
                      {cycle.confidence || cycle.risk_score || 0}
                    </div>
                    <div style={{ color: '#65705f', fontSize: 12 }}>confidence</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Trade ID</th>
                  <th>Risk Score</th>
                  <th>Label</th>
                  <th>Reason</th>
                  <th>Detected</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((log, idx) => (
                  <tr key={`${log.trade_id}-${idx}`}>
                    <td style={{ color: '#808779', fontFamily: 'monospace' }}>#{log.trade_id}</td>
                    <td style={{ fontWeight: 900 }}>{log.risk_score}</td>
                    <td><span className={badgeClass(log.risk_score)}>{log.risk_label || (Number(log.risk_score || 0) >= 70 ? 'HIGH' : Number(log.risk_score || 0) >= 40 ? 'MED' : 'LOW')}</span></td>
                    <td>{log.reason || 'Suspicious circular trading detected'}</td>
                    <td style={{ color: '#7d8578' }}>{log.detected_at ? new Date(log.detected_at).toLocaleString() : '—'}</td>
                  </tr>
                ))}
                {!logs.length && (
                  <tr>
                    <td colSpan="5">
                      <div className="empty-state">Risk logs will appear here live.</div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
